const $json = $input.first().json;
const raw = $json.choices?.[0]?.message?.content ?? '';
const t = raw.replace(/^```(json)?|```$/g, '').trim(); const j = t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1); let out; try { out = JSON.parse(j); } catch (e0) { let r = '', inS = false, esc = false; for (const ch of j) { if (inS && !esc && (ch === '\n' || ch === '\r' || ch === '\t')) { r += ch === '\n' ? '\\n' : ch === '\r' ? '' : ' '; continue; } if (ch === '"' && !esc) inS = !inS; esc = !esc && ch === '\\'; r += ch; } out = undefined; try { out = JSON.parse(r); } catch (e1) {} } if (out === undefined) for (let k = j.length - 2; k > 0 && out === undefined; k--) { if (j[k] !== '}') continue; try { out = JSON.parse(j.slice(0, k) + j.slice(k + 1)); } catch (e2) {} } if (out === undefined) try { out = JSON.parse(j); } catch (e) { throw new Error('LLM did not return JSON: ' + raw.slice(0, 300)); }
const items = (out.items || []).slice(0, 5);
if (items.length !== 5) throw new Error('Planner returned ' + items.length + ' items, expected 5');
return items.map(i => ({ json: { brief: i, attempt: 0, findings: [] } }));

const q = v => v === null || v === undefined ? 'null' : "'" + String(typeof v === 'object' ? JSON.stringify(v) : v).replaceAll("'", "''") + "'";
return $input.all().map(it => { const b = it.json.brief;
  return { json: { ...it.json, sql: `insert into cefflo_ce2.content (slot,type,platforms,funnel,format,world,pain,angle,hook,recycle_of,brief,status)
  values (${Number(b.slot)}, ${q(b.type)}, ${q('{' + (b.platforms || []).join(',') + '}')}::text[], ${q(b.funnel)}, ${q(b.format)}, ${q(b.world)}, ${q(b.pain)}, ${q(b.angle)}, ${q(b.hook_idea)},
  ${b.recycle_of ? q(b.recycle_of) + '::uuid' : 'null'}, ${q(b)}::jsonb, 'NEW')
  on conflict (run_date, slot, revisions) do update set brief = excluded.brief returning id` } }; });

return $input.all().map((it, i) => { const ctx = $('Build QA request').all()[i].json; const json = it.json; const raw = json.choices?.[0]?.message?.content ?? ''; const t = raw.replace(/^```(json)?|```$/g, '').trim(); const j = t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1); let out; try { out = JSON.parse(j); } catch (e0) { let r = '', inS = false, esc = false; for (const ch of j) { if (inS && !esc && (ch === '\n' || ch === '\r' || ch === '\t')) { r += ch === '\n' ? '\\n' : ch === '\r' ? '' : ' '; continue; } if (ch === '"' && !esc) inS = !inS; esc = !esc && ch === '\\'; r += ch; } out = undefined; try { out = JSON.parse(r); } catch (e1) {} } if (out === undefined) for (let k = j.length - 2; k > 0 && out === undefined; k--) { if (j[k] !== '}') continue; try { out = JSON.parse(j.slice(0, k) + j.slice(k + 1)); } catch (e2) {} } if (out === undefined) try { out = JSON.parse(j); } catch (e) { out = { verdict: 'FAIL', findings: [{ criterion: 'QA_UNAVAILABLE', evidence: 'QA returned no JSON; rewrite cleanly.' }] }; }
  if (ctx.script && ctx.script._invalid) out = { verdict: 'FAIL', findings: [{ criterion: 'FORMAT', evidence: 'Script was not valid JSON. Return valid JSON only.' }] };
  const pass = out.verdict === 'PASS'; return { json: { ...ctx, body: undefined, qa: out, pass, retry: !pass && ctx.attempt < 1,
    attempt: ctx.attempt + 1, findings: out.findings || [] } }; });

const q = v => v === null || v === undefined ? 'null' : "'" + String(typeof v === 'object' ? JSON.stringify(v) : v).replaceAll("'", "''") + "'";
return $input.all().map(it => ({ json: { ...it.json, sql: `update cefflo_ce2.content set script = ${q(it.json.script)}::jsonb, qa = ${q(it.json.qa)}::jsonb,
  hook = coalesce(${q(it.json.script.hook || it.json.script.title)}, hook), status = 'SCRIPTED', updated_at = now() where id = '${it.json.content_id}'` } }));
